'use strict';
const THEMES = {
 harvest: { name: 'Golden hour', note: 'Warm, bright & a little autumnal', emoji: '✳', accent: '#ad572f', dark: '#334b35', bg: '#fff9ee', light: '#eee6cf', headline: 'A bumper crop\nof good news.', kicker: 'THIS WEEK, WE GREW SOMETHING GREAT', intro: 'Big moves, small victories, and the people behind them. Here’s a little look at what we made happen together this week.', closing: 'Here’s to the people who make the good things happen. Same time next week?' },
 cosmic: { name: 'Out of this world', note: 'For a week of stellar work', emoji: '🚀', accent: '#7561b4', dark: '#29284b', bg: '#f7f4ff', light: '#e7e1f5', headline: 'One team.\nStellar things.', kicker: 'GOOD NEWS FROM OUR LITTLE UNIVERSE', intro: 'A whole constellation of wins, powered by our people. Here’s what took off across the company this week.', closing: 'Thanks for taking us a little further this week. Onward and upward!' },
 confetti: { name: 'Cue the confetti', note: 'Big celebration energy', emoji: '🎉', accent: '#c54d6a', dark: '#493749', bg: '#fff7f8', light: '#f4dfE6', headline: 'Good work.\nGreat people.', kicker: 'YOUR WEEKLY DOSE OF TEAM MAGIC', intro: 'Consider this your invitation to celebrate. These are the wins that deserve a little extra applause this week.', closing: 'A round of applause for everyone who made this week happen. Keep the good going!' },
 cozy: { name: 'The good news club', note: 'A cozy little catch-up', emoji: '☕', accent: '#916b45', dark: '#414b3e', bg: '#faf8f0', light: '#eae8d8', headline: 'Pour a cup.\nCatch the good.', kicker: 'FRESHLY BREWED TEAM WINS', intro: 'Settle in for a few good things from around the company. A little progress, a little gratitude, and plenty to be proud of.', closing: 'Thanks for all the care you put into your work. Enjoy a well-earned breather.' }
};
const KEY = 'weekly-wins-studio-v1';
function escapeHTML(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function richText(value) { return escapeHTML(value).replace(/\n/g, '<br>'); }
function safeURL(value) { try { const u = new URL(value); return u.protocol === 'https:' ? u.href : ''; } catch { return ''; } }
function localDate() { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function dateLabel(value) { const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value || ''); if(!match) return 'This week'; const d=new Date(Number(match[1]),Number(match[2])-1,Number(match[3])); return d.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}); }
function newDraft(sample=false) { const t=THEMES.harvest; return { company:'Concept3D', date:localDate(), subject:'This week’s wins ✳ A little good news from around the team', intro:t.intro, theme:'harvest', headline:t.headline, closing:t.closing, image:'', imageAlt:'A celebration of our team’s wins', fact:'', factSource:'', question:'', answer:'', showAnswer:false, sample, wins:sample ? [{sample:true,team:'Engineering',title:'A smoother experience, shipped.',body:'The team shipped improvements that make getting around a campus map feel even more effortless. A big thank-you to everyone who tested, refined, and brought it over the finish line.'},{sample:true,team:'Customer Success',title:'Turning feedback into forward motion.',body:'The team helped a customer bring their next big idea to life. Thoughtful collaboration, a happy partner, and a reminder of why we do what we do.'},{sample:true,team:'Sales & Marketing',title:'New conversations. New possibilities.',body:'A week of great conversations and meaningful connections. Cheers to the team putting our story out into the world.'}] : [] }; }
function normalizeDraft(s) { if(!s || typeof s !== 'object' || !Array.isArray(s.wins)) throw new Error('Invalid draft'); const out=newDraft(); for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer']) if(typeof s[k]==='string') out[k]=s[k].slice(0,20000); out.theme=THEMES[s.theme]?s.theme:'harvest'; out.showAnswer=s.showAnswer===true; out.sample=s.sample===true; out.wins=s.wins.slice(0,200).filter(w=>w&&typeof w==='object').map(w=>({sample:w.sample===true||(s.sample===true&&w.sample===undefined),team:String(w.team||'Team').slice(0,200),title:String(w.title||'').slice(0,1000),body:String(w.body||'').slice(0,20000)})); return out; }
function parseWins(raw) { let team='Team'; const wins=[]; for(let line of raw.split(/\r?\n/)){ line=line.trim().replace(/^[-*•]\s*/, ''); if(!line) continue; const heading=/^(.{1,80}):\s*$/.exec(line); if(heading){team=heading[1];continue;} const inline=/^([^:]{1,80}):\s+(.+)$/.exec(line); if(inline){team=inline[1];line=inline[2];} wins.push({team,title:'',body:line}); } return wins; }
function emailHTML(s) {
 const t=THEMES[s.theme]||THEMES.harvest, groups=new Map();
 for(const w of s.wins){ if(!w.title.trim()&&!w.body.trim())continue;const name=w.team.trim()||'Team';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(w); }
 const sections=[...groups].map(([team,wins],i)=>`<tr><td style="padding:24px 32px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-top:1px solid ${t.light}"><tr><td style="padding-top:20px"><p style="margin:0 0 10px;color:${t.accent};font:700 10px Arial,sans-serif;letter-spacing:1.5px">${String(i+1).padStart(2,'0')} &nbsp; ${escapeHTML(team.toUpperCase())}</p>${wins.map(w=>`${w.title?`<h2 style="margin:8px 0 10px;font:normal 24px Georgia,serif;color:${t.dark}">${richText(w.title)}</h2>`:''}${w.body?`<p style="font:14px/1.8 Arial,sans-serif;margin:0 0 15px;color:#535b50">${richText(w.body)}</p>`:''}`).join('')}</td></tr></table></td></tr>`).join('');
 const image=safeURL(s.image),source=safeURL(s.factSource);
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(s.subject)}</title></head><body style="margin:0;padding:0;background:${t.bg}"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${t.bg}"><tr><td align="center"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:${t.bg}"><tr><td style="padding:27px 32px 0"><table role="presentation" width="100%"><tr><td style="font:700 11px Arial,sans-serif;letter-spacing:2px;color:${t.dark}">${escapeHTML(s.company||'OUR TEAM')} <span style="color:${t.accent}"> / </span> WEEKLY WINS</td><td align="right" style="font:10px Arial,sans-serif;color:#7c8072">${escapeHTML(dateLabel(s.date))}</td></tr></table></td></tr><tr><td style="padding:34px 32px 0"><div style="font:10px Arial,sans-serif;letter-spacing:1.5px;color:${t.accent};font-weight:bold">${t.kicker}</div><table role="presentation" width="100%"><tr><td style="padding-top:15px"><h1 style="font:normal 46px/1.06 Georgia,serif;letter-spacing:-1.5px;color:${t.dark};margin:0">${richText(s.headline)}</h1></td><td align="right" style="font:normal 65px Georgia,serif;color:${t.accent};padding-left:8px">${t.emoji}</td></tr></table><p style="font:14px/1.8 Arial,sans-serif;color:#6c7364;margin:20px 0 0">${richText(s.intro)}</p></td></tr>${image?`<tr><td style="padding:24px 32px 0"><img src="${escapeHTML(image)}" alt="${escapeHTML(s.imageAlt||'Team celebration')}" width="536" style="display:block;width:100%;max-width:536px;height:auto;border-radius:8px"></td></tr>`:''}${sections||'<tr><td style="padding:32px;color:#7c8072;font:14px Arial,sans-serif">Add your team’s wins to see them here.</td></tr>'}${s.fact.trim()?`<tr><td style="padding:22px 32px 0"><table role="presentation" width="100%" style="background:${t.light};border-radius:8px"><tr><td style="padding:20px"><p style="margin:0 0 9px;font:700 10px Arial,sans-serif;letter-spacing:1.4px;color:${t.dark}">✦ A LITTLE SOMETHING TO KNOW</p><p style="margin:0;font:14px/1.7 Arial,sans-serif;color:#535b50">${richText(s.fact)}</p>${source?`<p style="margin:10px 0 0;font:11px Arial,sans-serif"><a href="${escapeHTML(source)}" style="color:${t.accent}">Fact source ↗</a></p>`:''}</td></tr></table></td></tr>`:''}${s.question.trim()?`<tr><td style="padding:24px 32px 0"><p style="font:700 10px Arial,sans-serif;letter-spacing:1.5px;color:${t.accent};margin:0 0 10px">THE WEEKLY BRAIN TEASER</p><p style="font:normal 21px/1.4 Georgia,serif;color:${t.dark};margin:0">${richText(s.question)}</p></td></tr>`:''}<tr><td style="padding:30px 32px"><table role="presentation" width="100%" style="border-top:1px solid ${t.light}"><tr><td style="padding-top:23px"><p style="font:italic 19px/1.5 Georgia,serif;color:${t.dark};margin:0">${richText(s.closing)}</p><p style="font:10px Arial,sans-serif;letter-spacing:1px;color:#8c927f;margin:20px 0 0">MADE POSSIBLE BY YOU. &nbsp; ${t.emoji}</p>${s.question.trim()&&s.showAnswer&&s.answer.trim()?`<p style="font:11px/1.6 Arial,sans-serif;color:#7c8072;margin:24px 0 0"><strong>Trivia answer:</strong> ${richText(s.answer)}</p>`:''}</td></tr></table></td></tr></table></td></tr></table></body></html>`;
}
function emailText(s) { return `${s.company} | Weekly Wins | ${dateLabel(s.date)}\n\n${s.headline}\n\n${s.intro}\n\n${s.wins.map(w=>`${w.team}\n${w.title}\n${w.body}`).join('\n\n')}\n\n${s.fact?`Fun fact: ${s.fact}\n${safeURL(s.factSource)}\n\n`:''}${s.question?`Trivia: ${s.question}\n\n`:''}${s.closing}${s.question&&s.showAnswer&&s.answer?`\n\nTrivia answer: ${s.answer}`:''}`; }
if(typeof module!=='undefined') module.exports={escapeHTML,safeURL,parseWins,emailHTML,normalizeDraft,newDraft};
if(typeof document!=='undefined') {
 let state;try{state=normalizeDraft(JSON.parse(localStorage.getItem(KEY)));}catch{state=newDraft(true);}
 const $=id=>document.getElementById(id); let toastTimer;
 function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved on this device';}catch{$('saveStatus').textContent='Not saved — download a draft';}}
 function preview(){state.sample=state.wins.some(w=>w.sample);const html=emailHTML(state);$('emailPreview').srcdoc=html;$('previewSubject').textContent=state.subject||'Weekly wins';$('previewSender').textContent=state.company||'Our team';$('winCount').textContent=`${state.wins.filter(w=>w.title.trim()||w.body.trim()).length} wins`;$('sampleTag').hidden=!state.sample;save();}
 function renderCards(){ $('winCards').innerHTML=state.wins.map((w,i)=>`<div class="win-card"><div class="win-top"><label>Team<input data-i="${i}" data-field="team" aria-label="Team for win ${i+1}" value="${escapeHTML(w.team)}"></label><button class="remove-win" data-remove="${i}" aria-label="Remove win ${i+1}">×</button></div><label>Win headline <span style="font-weight:400;color:#959b8a">(optional)</span><input data-i="${i}" data-field="title" value="${escapeHTML(w.title)}" placeholder="What’s worth celebrating?"></label><label>The good stuff<textarea data-i="${i}" data-field="body" rows="3" placeholder="Share what happened and give people credit…">${escapeHTML(w.body)}</textarea></label></div>`).join(''); }
 function renderThemes(){ $('themes').innerHTML=Object.entries(THEMES).map(([id,t])=>`<button class="theme-choice" data-theme="${id}" aria-pressed="${state.theme===id}"><span class="theme-emoji">${t.emoji}</span><strong>${t.name}</strong><small>${t.note}</small><span class="swatches"><i style="background:${t.dark}"></i><i style="background:${t.accent}"></i><i style="background:${t.light}"></i></span></button>`).join(''); }
 function render(){ for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer'])$(k).value=state[k];$('showAnswer').checked=state.showAnswer;renderCards();renderThemes();preview(); }
 for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer'])$(k).addEventListener('input',e=>{state[k]=e.target.value;preview();});
 $('showAnswer').addEventListener('change',e=>{state.showAnswer=e.target.checked;preview();});
 document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));for(const name of ['wins','theme','extras'])$(name+'Panel').hidden=name!==b.dataset.tab;}));
 $('winCards').addEventListener('input',e=>{const i=e.target.dataset.i,field=e.target.dataset.field;if(i!==undefined&&field){state.wins[Number(i)][field]=e.target.value;preview();}});
 $('winCards').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){state.wins.splice(Number(b.dataset.remove),1);renderCards();preview();}});
 $('addWin').addEventListener('click',()=>{state.wins.push({team:'',title:'',body:''});renderCards();preview();$('winCards').lastElementChild.querySelector('input').focus();});
 $('parseBatch').addEventListener('click',()=>{const wins=parseWins($('batch').value);if(!wins.length)return toast('Paste a few wins first.');state.wins.push(...wins);$('batch').value='';renderCards();preview();toast(`Added ${wins.length} wins. Review the team names and wording below.`);});
 $('clearDemo').addEventListener('click',()=>{if(!state.sample)return toast('The sample wins have already been cleared.');state.wins=state.wins.filter(w=>!w.sample);state.sample=false;renderCards();preview();toast('Sample wins cleared. Ready for your team’s good news.');});
 $('themes').addEventListener('click',e=>{const b=e.target.closest('[data-theme]');if(!b)return;const old=THEMES[state.theme],next=THEMES[b.dataset.theme];for(const k of ['headline','intro','closing'])if(state[k]===old[k])state[k]=next[k];state.theme=b.dataset.theme;render();});
 $('desktop').addEventListener('click',()=>{$('emailContainer').classList.remove('mobile');$('desktop').setAttribute('aria-pressed','true');$('mobile').setAttribute('aria-pressed','false');});
 $('mobile').addEventListener('click',()=>{$('emailContainer').classList.add('mobile');$('desktop').setAttribute('aria-pressed','false');$('mobile').setAttribute('aria-pressed','true');});
 function download(content,type,name){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 $('download').addEventListener('click',()=>{download(emailHTML(state),'text/html',`weekly-wins-${state.date||localDate()}.html`);toast('HTML downloaded. Open it in a browser to copy the formatted email.');});
 $('backup').addEventListener('click',()=>download(JSON.stringify(state,null,2),'application/json',`weekly-wins-draft-${state.date||localDate()}.json`));
 $('importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw new Error();const candidate=normalizeDraft(JSON.parse(await f.text()));if(!confirm('Replace the current edition with this saved draft?'))return;state=candidate;render();toast('Saved draft loaded.');}catch{toast('That file isn’t a supported weekly wins draft.');}finally{e.target.value='';}});
 $('copySubject').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.subject);toast('Subject copied.');}catch{toast('Clipboard unavailable. Copy the subject from the editor.');}});
 $('copyEmail').addEventListener('click',async()=>{if(state.sample&&!confirm('This email still contains sample content. Copy it anyway?'))return;try{const html=emailHTML(state),text=emailText(state);if(navigator.clipboard?.write&&typeof ClipboardItem!=='undefined')await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]);else{const el=document.createElement('div');el.innerHTML=html;el.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(el);const range=document.createRange();range.selectNodeContents(el);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);const ok=document.execCommand('copy');selection.removeAllRanges();el.remove();if(!ok)throw new Error();}toast('Formatted email copied! Paste into Gmail’s message body.');}catch{toast('Couldn’t copy rich text here. Download the HTML, open it, and copy from your browser.');}});
 $('reset').addEventListener('click',()=>{if(!confirm('Start a fresh edition? Download your current draft first if you want to keep it.'))return;const company=state.company;state=newDraft(false);state.company=company;render();toast('A fresh week, a fresh edition.');});
 render();
}
